sys_ux_data_broker_transform.script:
function transform(input) {
    var selecteduser = input.userID;
	var loginUser = gs.getUserID();
	gs.info("selected user"+selecteduser);
    function isUserInGroup(userSysId, groupname) {
        var group = new GlideRecord('sys_user_grmember');
        group.addEncodedQuery("group.name=" + groupname + "^user=" + userSysId);
        group.query();

        // If a record is found, the user is a member of the group
        return group.next();
    }

    var reportlist = ["My Accelerators", "Certifications Achieved", "Feedbacks Recieved", "My Milestones", "Milestones of your resources", "# employees achieved 5+ Milestones (Compliant Employees)", "# employees achieved < 5 Milestones (Non-Compliant Employees)", "Milestones by Quarter", "Employee wise Compliance Percent"];

    var reportobj = [{
        "id": "none",
        "label": "-- None --"
    }];
    var len = 0;

    if (isUserInGroup(loginUser, 'GRC Senior Managers') || isUserInGroup(loginUser, 'GRC Managers')) {
        if (selecteduser) {
            len = 9;
        } else {
            len = 4;
        }
    } else {
        len = 4;
    }

    for (var i = 0; i < len; i++) {
        reportobj.push({
            "id": reportlist[i].toString(),
            "label": reportlist[i].toString()
        });
    }


    return reportobj;
}
